{
  "task_summary": "评审本机演示的修书咨询登记流程：核对两个时段，选择下午二层服务台，在核对页返回选择后再次核对并提交，查看登记结果；后续按三条设计要求分别记录观察及证据。本阶段仅整理材料。",
  "target_user_summary": "",
  "review_tasks": [
    {
      "task_id": "TASK01",
      "text": "核对两个时段及其服务台，并更换为下午的二层服务台。",
      "success_criteria": "可同时核对时段和服务台，并选中下午选项。",
      "evidence_ids": ["ev-c609eb48befe403ebb2eeebeaf0a9644"],
      "branches": []
    },
    {
      "task_id": "TASK02",
      "text": "进入核对页，使用“返回选择”回到上一步，再次核对所选时段和服务台。",
      "success_criteria": "返回后保留上一次选择的时段和服务台。",
      "evidence_ids": ["ev-c609eb48befe403ebb2eeebeaf0a9644"],
      "branches": [
        {
          "branch_id": "BR01",
          "trigger": "在核对页返回选择",
          "expected_outcome": "保留上一次选择的时段和服务台。",
          "evidence_ids": ["ev-c609eb48befe403ebb2eeebeaf0a9644"],
          "basis": "explicit"
        }
      ]
    },
    {
      "task_id": "TASK03",
      "text": "为下午的二层服务台完成登记，并查看完成页的登记结果。",
      "success_criteria": "完成页显示用户最终确认的时段和服务台。",
      "evidence_ids": ["ev-c609eb48befe403ebb2eeebeaf0a9644"],
      "branches": [
        {
          "branch_id": "BR02",
          "trigger": "提交登记",
          "expected_outcome": "完成页显示用户最终确认的时段和服务台。",
          "evidence_ids": ["ev-c609eb48befe403ebb2eeebeaf0a9644"],
          "basis": "explicit"
        }
      ]
    },
    {
      "task_id": "TASK04",
      "text": "需要重新开始时，刷新页面或在完成页按“重新开始”复位。",
      "success_criteria": "回到选择时段页开始新一轮。",
      "evidence_ids": ["ev-c609eb48befe403ebb2eeebeaf0a9644"],
      "branches": [
        {
          "branch_id": "BR03",
          "trigger": "刷新页面或在完成页按“重新开始”",
          "expected_outcome": "复位，从选择时段页开始。",
          "evidence_ids": ["ev-c609eb48befe403ebb2eeebeaf0a9644"],
          "basis": "explicit"
        }
      ]
    }
  ],
